-- composition of rule kernels column_lifetime x limit_pushdown (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1), kb AS (SELECT (SELECT MAX (a1.c0) FROM t4 AS a1 WHERE (EXISTS (SELECT 1::bigint AS c0))) AS c0, '2000-01-01'::date AS c1) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS ka) + (SELECT count(*) FROM (SELECT (SELECT MAX (a1.c0) FROM t4 AS a1 WHERE (EXISTS (SELECT 1::bigint AS c0))) AS c0, '2000-01-01'::date AS c1) AS kb)
